import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";

import { ProfessionalReviewApp } from "./ProfessionalReviewApp";
import { hostBridge } from "./test-fixtures";
import type { ReviewProjection, ReviewWidgetData } from "./types";
// Deterministic schema 3 output generated by tests/dump_review_projections.py via
// the Python ReviewService. Vite reads the on-disk file at test time so the
// component is exercised against the authoritative runtime/UI contract. This
// fixture is not a real customer project or desktop PowerPoint/WPS evidence.
import contentData from "./__fixtures__/review-projection.content.json";
import visualData from "./__fixtures__/review-projection.visual.json";

function loadReview(type: "content" | "visual"): ReviewWidgetData {
  const review = (type === "content" ? contentData : visualData) as unknown as ReviewProjection;
  return {
    surface: "review",
    selectedProjectRoot: "/managed/project",
    snapshotRevision: 1,
    review,
  };
}

function countPages(type: "content" | "visual", review: ReviewProjection): number {
  const prefix = type === "content" ? "slide-" : "visual-slide-";
  return review.sections.filter((s) => s.anchor.startsWith(prefix)).length;
}

describe("professional review surface fed by real backend projection", () => {
  it("renders the real content projection with correct page count and no structure-as-page bug", () => {
    const data = loadReview("content");
    const { container } = render(
      <ProfessionalReviewApp initialData={data} bridge={hostBridge(data).bridge} />
    );

    const expectedPages = countPages("content", data.review);
    expect(expectedPages).toBe(2);

    const pageSheets = container.querySelectorAll('article.review-sheet[id^="slide-"]');
    expect(pageSheets.length).toBe(expectedPages);

    // A content-structure section, when present, is standing metadata and never
    // a slide page. Schema 3 may project the same structure inside overview.
    expect(container.querySelector('article.review-sheet[id="content-structure"]')).toBeNull();
    const optionalStructure = container.querySelector('section.review-doc-section[id="content-structure"]');
    if (data.review.sections.some((section) => section.anchor === "content-structure")) {
      expect(optionalStructure).toBeTruthy();
    }

    // Page-count chip reflects only slide pages (also echoed in the outline).
    expect(screen.getAllByText(`${expectedPages} 页`).length).toBeGreaterThan(0);
    expect(screen.getAllByText("讲解备注").length).toBe(expectedPages);
    expect(screen.getByText("解释来源")).toBeInTheDocument();
    expect(screen.getByText("讲解备注 2")).toBeInTheDocument();
  });

  it("renders the real visual projection without double rendering and routes fields correctly", () => {
    const data = loadReview("visual");
    const { container } = render(
      <ProfessionalReviewApp initialData={data} bridge={hostBridge(data).bridge} />
    );

    const expectedPages = countPages("visual", data.review);
    expect(expectedPages).toBeGreaterThan(0);

    const pageSheets = container.querySelectorAll('article.review-sheet[id^="visual-slide-"]');
    expect(pageSheets.length).toBe(expectedPages);

    // visual-framework and deck-design-system are standing sections, each rendered once.
    expect(container.querySelectorAll('[id="visual-framework"]').length).toBe(1);
    expect(container.querySelectorAll('[id="deck-design-system"]').length).toBe(1);

    expect(screen.getAllByText(`${expectedPages} 页`).length).toBeGreaterThan(0);

    // visible_copy (frozen text) survives into the frozen-content column.
    expect(screen.getAllByText(/五套系统/).length).toBeGreaterThan(0);
    // page_family routes to the visual implementation contract column.
    expect(screen.getAllByText("页面家族").length).toBeGreaterThan(0);
    expect(screen.getAllByText("证据页").length).toBeGreaterThan(0);
  });
});
